#pragma once
int runBrowser432(){
 juce::ScopedJuceInitialiser_GUI gui;LibraryPreparation::checksPaused=true;std::cout.setf(std::ios::unitbuf);
 auto require=[](bool ok,const char* why){if(!ok)throw std::runtime_error(why);};auto wait=[](auto predicate){double until=juce::Time::getMillisecondCounterHiRes()+15000;while(!predicate()&&juce::Time::getMillisecondCounterHiRes()<until){CFRunLoopRunInMode(kCFRunLoopDefaultMode,.003,true);juce::Thread::sleep(2);}return predicate();};
 try{
  Processor p(false);p.autoSave=false;require(p.detectStrength==80&&p.importDetectStrength==80&&p.preferredSliceMethod==1,"new slice defaults");auto audio=std::make_shared<AudioData>();audio->rate=48000;audio->buffer.setSize(1,48000);audio->buffer.clear();audio->path=LibraryStore::root().getChildFile("unsaved.wav").getFullPathName();require(p.installAudio(audio,false,0,false),"install sample");p.detectStrength=33;auto saved=p.configurationXml();p.detectStrength=80;require(p.applyConfiguration(*saved,false)&&p.detectStrength==33,"saved strength preserved");
  auto root=LibraryStore::root().getChildFile("Files"),destination=root.getChildFile("Destination");destination.createDirectory();LibraryStore::addLibraryRoot(root);juce::Array<juce::File> selected;juce::AudioBuffer<float> tone(1,1000);tone.clear();tone.setSample(0,20,.2f);for(int i=0;i<3;++i){auto f=root.getChildFile("move "+juce::String(i)+".wav");require(writeRenderedAudio(f,tone,48000),"move fixture");selected.add(f);}LibraryStore::addTag(selected,"bulk-move");
  Editor e(p);e.setSize(1400,1120);e.diagnosticQuietAnalysis();e.browserAutoLoad=false;e.navigateForCheck(root);require(wait([&]{return e.recursiveReady&&e.visible.contains(selected[0])&&e.pendingCatalogSignature.isEmpty();}),"browser fixture ready");
  {juce::ScopedValueSetter<bool> suppress(e.suppressBrowserLoad,true);e.files.deselectAllRows();for(auto f:selected)e.files.selectRow(e.visible.indexOf(f),true,false);e.selectBrowserRowForClick(e.visible.indexOf(selected[1]),juce::ModifierKeys::leftButtonModifier);}
  require(e.files.getNumSelectedRows()==3&&e.fileContextTargets(e.visible.indexOf(selected[1])).size()==3,"mouse down retains complete move payload");auto payload=e.fileContextTargets(e.visible.indexOf(selected[1]));auto began=juce::Time::getMillisecondCounterHiRes();e.moveBrowserFiles(payload,destination);require(juce::Time::getMillisecondCounterHiRes()-began<20,"move request non-blocking");require(!e.visible.isEmpty(),"move retains old browser until update");require(wait([&]{return !e.movingBrowserFiles&&e.visible.contains(destination.getChildFile(selected[0].getFileName()));}),"bulk move and incremental browser completion");for(auto f:selected){auto moved=destination.getChildFile(f.getFileName());require(!f.exists()&&moved.existsAsFile(),"all files moved rather than copied");require(LibraryStore::tagsFor(LibraryStore::read("tags.json"),moved).contains("bulk-move"),"move retains metadata");}
  juce::Array<juce::File> tagged;for(int i=0;i<201;++i)tagged.add(root.getChildFile("tag "+juce::String(i)+".wav"));LibraryStore::addTag(tagged,"one, two, three");auto meta=LibraryStore::read("tags.json");auto impact=LibraryStore::tagRemovalImpact(meta,tagged,{},true);require(impact.tags==603&&impact.files==201&&impact.needsConfirmation(),"count tag assignments");auto small=tagged;small.removeLast();impact=LibraryStore::tagRemovalImpact(meta,small,"one",false);require(impact.tags==200&&!impact.needsConfirmation(),"exact threshold is not over 200");auto duplicate=tagged;duplicate.add(tagged[0]);require(LibraryStore::tagRemovalImpact(meta,duplicate,"one",false).tags==201,"duplicate targets counted once");
  auto modal=[](){return juce::ModalComponentManager::getInstance()->getModalComponent(0);};
  e.removeAssignedTags(tagged,{},true);require(wait([&]{return modal()!=nullptr;}),"large removal asks confirmation");require(LibraryStore::tagsFor(LibraryStore::read("tags.json"),tagged[0]).contains("three"),"no write before confirmation");modal()->exitModalState(0);require(wait([&]{return modal()==nullptr&&e.browserEditPool.getNumJobs()==0;}),"cancel dialog");require(LibraryStore::tagsFor(LibraryStore::read("tags.json"),tagged[0]).contains("three"),"cancel leaves metadata intact");
  e.removeAssignedTags(tagged,{},true);require(wait([&]{return modal()!=nullptr;}),"second confirmation");modal()->exitModalState(1);require(wait([&]{return LibraryStore::tagsFor(LibraryStore::read("tags.json"),tagged[0]).isEmpty();}),"confirmed removal applies");require(LibraryStore::tagsFor(LibraryStore::read("tags.json"),tagged[200]).isEmpty(),"all confirmed targets removed");
  LibraryStore::addTag(tagged,"single");e.removeAssignedTags(small,"single");require(wait([&]{return LibraryStore::tagsFor(LibraryStore::read("tags.json"),small[0]).isEmpty();}),"200-removal applies without prompt");require(modal()==nullptr&&!LibraryStore::tagsFor(LibraryStore::read("tags.json"),tagged[200]).isEmpty(),"no prompt and unselected target preserved");
  std::cout<<"Bulk selection/payload, three real file+metadata moves, no blank browser, 200/201 removal threshold, Cancel/Confirm/no-prompt paths and 80% defaults with saved recall passed\n";return 0;
 }catch(const std::exception& error){std::cerr<<"FAIL: "<<error.what()<<"\n";return 4321;}
}
